<script setup lang="ts">import type {Run} from '../types/domain';import {number,probability} from '../utils/format';defineProps<{run:Run}>();</script><template><section class="run-summary"><p class="eyebrow">BALANCED FIXED EFFECTS</p><h2>{{run.result.n}} <small>个独立试片</small></h2><dl><div><dt>每处理格</dt><dd>{{run.result.per_cell}}片</dd></div><div><dt>格内MSE</dt><dd>{{number(run.result.mse,4)}}</dd></div><div><dt>交互 p</dt><dd>{{probability(run.result.anova?.[2].p)}}</dd></div><div><dt>预设对比 / Holm拒绝</dt><dd>{{run.result.family_size}} / {{run.result.holm_rejections}}</dd></div></dl><p :class="run.result.interaction_detected?'interaction-warning':'interaction-note'">{{run.result.interaction_detected?'交互有统计证据：温度作用取决于釉层。主效应是跨釉层平均，不作为普遍作用。':'当前未检出交互；仍应结合区间、样本与实验前提解释。'}}</p></section></template>
